class Solution:
    def minCostSetCookingTime(self, startAt: int, moveCost: int, pushCost: int, targetSeconds: int) -> int:
        def cost(digits: str) -> int:
            cur, total = startAt, 0
            for ch in digits:
                d = ord(ch) - 48
                if d != cur:
                    total += moveCost
                    cur = d
                total += pushCost
            return total
        best = float('inf')
        for m in range(100):
            s = targetSeconds - 60 * m
            if 0 <= s <= 99:
                digits = (str(m) if m else '') + str(s).zfill(2)
                best = min(best, cost(digits))
        return best

