class Solution {
public:
    int minCostSetCookingTime(int startAt, int moveCost, int pushCost, int targetSeconds) {
        auto cost = [&](const string& digits) {
            int cur = startAt;
            long long total = 0;
            for (char ch : digits) {
                int d = ch - '0';
                if (d != cur) { total += moveCost; cur = d; }
                total += pushCost;
            }
            return total;
        };
        long long best = LLONG_MAX;
        for (int m = 0; m <= 99; ++m) {
            int s = targetSeconds - 60 * m;
            if (s < 0 || s > 99) continue;
            string digits = (m ? to_string(m) : "") + (s < 10 ? "0" : "") + to_string(s);
            best = min(best, cost(digits));
        }
        return (int)best;
    }
};

