class Solution {
    public int minCostSetCookingTime(int startAt, int moveCost, int pushCost, int targetSeconds) {
        long best = Long.MAX_VALUE;
        for (int m = 0; m <= 99; m++) {
            int s = targetSeconds - 60 * m;
            if (s < 0 || s > 99) continue;
            String digits = (m > 0 ? String.valueOf(m) : "") + (s < 10 ? "0" : "") + s;
            int cur = startAt;
            long total = 0;
            for (char ch : digits.toCharArray()) {
                int d = ch - '0';
                if (d != cur) { total += moveCost; cur = d; }
                total += pushCost;
            }
            best = Math.min(best, total);
        }
        return (int) best;
    }
};

